function indonesiaRegionOptions(selected=''){
 const values=new Set();
 const groups=indonesiaRegions.map(p=>`<optgroup label="${escapeHtml(p.province)}">${p.cities.map(c=>{const value=c.code.startsWith('11.')?c.name.replace(/^(Kabupaten|Kota) /,''):c.name;values.add(value);return `<option value="${escapeHtml(value)}"${value===selected?' selected':''}>${escapeHtml(c.name)}</option>`}).join('')}</optgroup>`).join('');
 return '<option value="">Pilih kabupaten / kota</option>'+(selected&&!values.has(selected)?`<option value="${escapeHtml(selected)}" selected>${escapeHtml(selected)}</option>`:'')+groups;
}

