function regionCode(value){
 const normalized=String(value||'').trim().toLocaleLowerCase('id-ID').replace(/^(kabupaten|kab\.|kota)\s+/,'');
 return indonesiaRegions.flatMap(p=>p.cities).find(c=>c.name.toLocaleLowerCase('id-ID').replace(/^(kabupaten|kota)\s+/,'')===normalized)?.code||'';
}
function indonesiaDistrictOptions(region,selected=''){
 const names=indonesiaDistricts[regionCode(region)]||[];
 return '<option value="">'+(region?'Pilih kecamatan':'Pilih kabupaten / kota terlebih dahulu')+'</option>'+(selected&&!names.includes(selected)?`<option value="${escapeHtml(selected)}" selected>${escapeHtml(selected)} (tersimpan)</option>`:'')+names.map(n=>`<option value="${escapeHtml(n)}"${n===selected?' selected':''}>${escapeHtml(n)}</option>`).join('');
}
function bindAdministrativeFields(region,district,selected=''){
 district.innerHTML=indonesiaDistrictOptions(region.value,selected);
 district.disabled=!region.value&&!selected;
 region.addEventListener('change',()=>{district.innerHTML=indonesiaDistrictOptions(region.value);district.disabled=!region.value});
}
function mountProjectDistrict(form,p){
 const region=form.querySelector('[name="region"]'),old=form.querySelector('[name="district"]');if(!region||!old)return;
 const select=document.createElement('select');select.name='district';old.replaceWith(select);bindAdministrativeFields(region,select,p.district||'');
}
